import{_ as e,o as r,c as o,a2 as d}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/ko/import-text-preview.png",p=JSON.parse('{"title":"가져오기와 다른 형식","description":"","frontmatter":{},"headers":[],"relativePath":"features/import.md","filePath":"features/import.md"}'),i={name:"features/import.md"};function s(l,t,n,c,h,m){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="가져오기와-다른-형식" tabindex="-1">가져오기와 다른 형식 <a class="header-anchor" href="#가져오기와-다른-형식" aria-label="Permalink to &quot;가져오기와 다른 형식&quot;">​</a></h1><p>SQL(<code>CREATE TABLE</code>)·DBML·Mermaid·Markdown에서 모델을 가져오는 방법과, 다른 <code>.erm</code> 파일에서 객체를 가져오는 방법을 설명합니다. DB에 접속해 가져오기는 <a href="/relio/features/database">DB 연동</a>에 있습니다.</p><h2 id="가져오기-메뉴" tabindex="-1">가져오기 메뉴 <a class="header-anchor" href="#가져오기-메뉴" aria-label="Permalink to &quot;가져오기 메뉴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>하는 일</th></tr></thead><tbody><tr><td>파일 › 가져오기 ▸ › DB에서…</td><td>DB에 접속해 구조를 가져옵니다. <a href="/relio/features/database#db에서-가져오기">DB 연동</a></td></tr><tr><td>파일 › 가져오기 ▸ › 파일에서…</td><td>다른 <code>.erm</code> 파일의 객체를 골라 넣습니다.</td></tr><tr><td>파일 › 가져오기 ▸ › SQL·DBML·Mermaid·Markdown에서…</td><td>글 형식 파일이나 붙여 넣은 글에서 모델을 만듭니다. 문서가 없어도 쓸 수 있습니다.</td></tr></tbody></table><p><code>.sql</code> · <code>.ddl</code> · <code>.dbml</code> · <code>.mmd</code> · <code>.mermaid</code> · <code>.md</code> 파일을 창에 끌어다 놓거나 파일 › 열기…로 열어도 이 가져오기 창이 열립니다(바로 넣지 않음).</p><h2 id="sql·dbml·mermaid·markdown에서-가져오기" tabindex="-1">SQL·DBML·Mermaid·Markdown에서 가져오기 <a class="header-anchor" href="#sql·dbml·mermaid·markdown에서-가져오기" aria-label="Permalink to &quot;SQL·DBML·Mermaid·Markdown에서 가져오기&quot;">​</a></h2><h3 id="입력" tabindex="-1">입력 <a class="header-anchor" href="#입력" aria-label="Permalink to &quot;입력&quot;">​</a></h3><table tabindex="0"><thead><tr><th>칸</th><th>설명</th></tr></thead><tbody><tr><td>입력</td><td><strong>파일</strong> 또는 <strong>붙여넣기</strong>. 파일은 32MB, 붙여넣기는 8MB까지입니다.</td></tr><tr><td>파일 경로</td><td><code>.sql</code> · <code>.ddl</code> · <code>.dbml</code> · <code>.mmd</code> · <code>.mermaid</code> · <code>.md</code>. **찾아보기…**로 고릅니다.</td></tr><tr><td>인코딩</td><td>**자동 (BOM·UTF-8)**이 기본입니다. BOM이 없고 UTF-8이 아닌 파일은 인코딩을 고르라고 묻습니다(추측하지 않음).</td></tr><tr><td>입력 형식</td><td>자동 판별 · SQL · DBML · Mermaid · Markdown</td></tr><tr><td>방언</td><td>SQL일 때 — 자동 판별 · PostgreSQL · MySQL/MariaDB · Oracle · SQL Server · 표준 SQL</td></tr></tbody></table><p><code>pg_dump</code>·<code>mysqldump</code>·SSMS 스크립트·Oracle DDL처럼 <code>CREATE TABLE</code>이 든 파일을 그대로 읽습니다. 읽을 수 없는 문장은 건너뛰고 경고로 알립니다.</p><h3 id="가져올-곳과-옵션" tabindex="-1">가져올 곳과 옵션 <a class="header-anchor" href="#가져올-곳과-옵션" aria-label="Permalink to &quot;가져올 곳과 옵션&quot;">​</a></h3><ul><li><strong>가져올 곳</strong> — <strong>새 문서</strong>(이름 없는 새 탭) 또는 <strong>현재 문서에 합치기</strong>. 열린 문서가 없거나 읽기 전용이면 새 문서만 됩니다.</li><li>새 문서의 DB는 형식이 알려 주는 DB를 씁니다. 형식이 DB를 알려 주지 않으면 고른 DB를 씁니다(SQL 방언을 알면 그 DB).</li><li><strong>주석 해석</strong> — 주석을 어디에 넣을지: <strong>자동 (논리명 : 설명)</strong> · <strong>설명으로만</strong> · <strong>논리명으로만</strong>.</li><li><strong>따옴표 없는 이름을 DB 규칙대로 (대문자·소문자)</strong> — 켜면 따옴표 없는 이름을 그 DB 규칙대로 대문자나 소문자로 바꿉니다.</li></ul><h3 id="미리-보기" tabindex="-1">미리 보기 <a class="header-anchor" href="#미리-보기" aria-label="Permalink to &quot;미리 보기&quot;">​</a></h3><p><strong>미리 보기</strong>를 누르면 문서에 넣기 전에 찾은 테이블 · 컬럼 · 관계 · 인덱스 수와 경고·참고를 봅니다. 큰 파일은 &quot;읽는 중… n초&quot;가 보이고, <strong>취소</strong>를 누르면 멈추고 아무것도 바꾸지 않습니다. <strong>뒤로</strong>로 입력을 고칩니다.</p><figure class="shot" data-scene="import-text-preview"><img src="'+a+'" alt="가져오기 미리 보기 — 찾은 테이블·컬럼·관계 수와 경고" loading="lazy"><figcaption>가져오기 미리 보기 — 찾은 테이블·컬럼·관계 수와 경고</figcaption></figure><h3 id="이름이-겹칠-때" tabindex="-1">이름이 겹칠 때 <a class="header-anchor" href="#이름이-겹칠-때" aria-label="Permalink to &quot;이름이 겹칠 때&quot;">​</a></h3><p>현재 문서에 합칠 때 이름이 같은 객체가 있으면 <strong>가져오기</strong>를 누른 뒤 처리 방법을 고릅니다.</p><table tabindex="0"><thead><tr><th>처리</th><th>하는 일</th></tr></thead><tbody><tr><td>덮어쓰기</td><td>내용만 바꾸고 위치·색·카테고리는 그대로 둡니다.</td></tr><tr><td>건너뛰기</td><td>그 객체는 가져오지 않습니다.</td></tr><tr><td>이름 바꿔 추가</td><td>다른 이름으로 더합니다.</td></tr></tbody></table><p><strong>남은 것 모두에 적용</strong>으로 한 번에 정하거나 &quot;(하나씩 고르기)&quot;로 객체마다 정합니다. 합친 결과는 되돌리기 한 번(<kbd>Ctrl</kbd>+<kbd>Z</kbd>)으로 모두 취소됩니다.</p><h3 id="결과" tabindex="-1">결과 <a class="header-anchor" href="#결과" aria-label="Permalink to &quot;결과&quot;">​</a></h3><p>가져온 뒤 <strong>가져오기 결과</strong>(또는 <strong>합치기 결과</strong>) 창에 만든(합친) 객체 수와 경고가 줄:열 · 종류 · 내용 · 건너뛴 글로 나옵니다. <strong>목록 복사</strong>로 복사할 수 있고, 같은 경고가 문제 목록에도 남습니다.</p><div class="tip custom-block"><p class="custom-block-title">팁</p><p>다른 도구에서 만든 SQL을 가져와 Relio에서 다듬은 뒤, 다시 DBML·Mermaid로 <a href="/relio/features/export#글-형식-내보내기-dbml·mermaid·markdown·모델-json">내보내기</a>할 수 있습니다. 명령줄 <code>relio import</code>로 화면 없이 <code>.erm</code>을 만들 수도 있습니다. <a href="/relio/features/cli#relio-import">명령줄</a></p></div><h2 id="다른-erm-파일에서-가져오기" tabindex="-1">다른 .erm 파일에서 가져오기 <a class="header-anchor" href="#다른-erm-파일에서-가져오기" aria-label="Permalink to &quot;다른 .erm 파일에서 가져오기&quot;">​</a></h2><p>파일 › 가져오기 ▸ › 파일에서…를 누르고 <code>.erm</code> 파일을 고르면 <strong>가져올 객체 (이 파일의 DB: …)</strong> 목록이 나옵니다. 테이블·뷰·노트·컬럼 그룹·시퀀스·트리거·테이블스페이스를 종류별로 묶어 보여 주며, 체크한 것을 지금 문서에 넣습니다(파일에 없는 종류는 나오지 않고, 이미지는 고를 수 없습니다). 처음에는 모두 체크되어 있고, 아래 <strong>단어를 병합</strong>을 켜 두면 내용이 같은 단어를 하나로 합칩니다.</p><ul><li>이름이 같은 객체는 위와 같이 덮어쓰기 · 건너뛰기 · 이름 바꿔 추가를 고릅니다.</li><li>카테고리는 이름(앞뒤 공백·대소문자 무시)이 같으면 새로 만들지 않고 그 카테고리에 소속만 더합니다.</li><li>가져오기 전체가 되돌리기 한 번입니다.</li></ul>',24)])])}const b=e(i,[["render",s]]);export{p as __pageData,b as default};
